INSERT INTO whatsapp_messages (
  lead_id, evolution_message_id, from_me, body, content_type, occurred_at
)
VALUES ($1, $2, $3, $4, $5, $6::timestamptz)
ON CONFLICT (lead_id, evolution_message_id) DO NOTHING
RETURNING id;

