const lead = $('Upsert lead').first().json || {};
const norm = $('Normalizar').first().json || {};
const ins = $input.first().json || {};
if (!ins.id) {
  return [];
}
const quoteRe = /OPCIONES DISPONIBLES|FORMULARIO DE REGISTRO|DETALLES DE TU ESTANCIA|cotizaci[oó]n y (fotos|videos)/i;
return [{
  json: {
    lead_id: lead.id,
    message_id: ins.id,
    from_me: Boolean(norm.from_me),
    is_quote: Boolean(norm.from_me && quoteRe.test(String(norm.body || ''))),
    body: String(norm.body || ''),
    content_type: String(norm.content_type || 'text'),
    stage_prev: lead.stage,
    quoted_at: lead.quoted_at || null,
    score_cierre_prev: Number(lead.score_cierre || 0),
    client_msg_count: Number(lead.client_msg_count || 0),
  },
}];

const lead = $('Actualizar contadores').first().json || {};
const prep = $('Preparar update').first().json || {};
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.body);
const current = rows.find((row) => Number(row.id) === Number(prep.message_id)) || null;
const signals = { pago: true, reserva: true, consulta: true, ninguna: true };
const rawSignal = current ? String(current.media_signal || '') : '';
const image_signal = signals[rawSignal] ? rawSignal : 'ninguna';
const mensaje = current && current.body ? String(current.body) : String(prep.body || '');
const lines = rows
  .slice()
  .reverse()
  .map((row) => {
    const who = row.from_me ? 'ASESORA' : 'CLIENTE';
    return `[${row.occurred_local || ''}] ${who}: ${row.body}`;
  });
return [{
  json: {
    lead_id: lead.id,
    message_id: prep.message_id,
    stage_prev: lead.stage,
    quoted_at: lead.quoted_at || null,
    client_msg_count: Number(lead.client_msg_count || 0),
    score_cierre_prev: Number(lead.score_cierre || 0),
    contexto: lines.join('\n') || 'Sin historial previo.',
    mensaje,
    image_signal,
  },
}];

const parsed = $input.first().json || {};
let raw = parsed.text || parsed.output || parsed.response || parsed.message || '';
if (raw && typeof raw === 'object') {
  raw = JSON.stringify(raw);
}
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
let data = {};
try {
  data = JSON.parse(raw);
} catch (e) {
  data = {};
}
const lead = $('Actualizar contadores').first().json || {};
const ctx = $('Armar contexto').first().json || {};
const body = String(ctx.mensaje || '');
const allText = `${ctx.contexto || ''}\n${body}`;
const closeRe = /para reservar|voy a pagar|puedo abonar|me la (puede )?apartar|pagar completo|hacer la reservaci|ya pagu[eé]|env[ií]o (el )?pago/i;
const stages = { en_proceso: true, concreto: true, pregunto_no_concreto: true, no_respondio: true };
const sentiments = { positivo: true, neutro: true, negativo: true, enfadado: true };
const clamp = (n, d) => {
  const v = Number(n);
  if (!Number.isFinite(v)) return d;
  return Math.max(0, Math.min(100, Math.round(v)));
};
let stage = stages[data.stage] ? data.stage : 'en_proceso';
let score_cierre = clamp(data.score_cierre, 0);
let score_engagement = clamp(data.score_engagement, 0);
let score_silencio = clamp(data.score_silencio, 0);
let score_potencial = clamp(data.score_potencial, 0);
let sentiment = sentiments[data.sentiment] ? data.sentiment : 'neutro';
let reason = String(data.reason || '').slice(0, 280);
if (closeRe.test(allText)) {
  stage = 'concreto';
  score_cierre = Math.max(score_cierre, 85);
  score_potencial = Math.min(score_potencial, 20);
  reason = reason || 'Señales explícitas de reserva o pago';
}
if (String(ctx.image_signal || '') === 'pago') {
  stage = 'concreto';
  score_cierre = Math.max(score_cierre, 85);
  score_potencial = Math.min(score_potencial, 20);
  reason = reason || 'Comprobante de pago en imagen';
}
if (lead.stage === 'concreto' || ctx.stage_prev === 'concreto') {
  stage = 'concreto';
  score_cierre = Math.max(score_cierre, Number(lead.score_cierre) || 85);
}
if (stage === 'no_respondio') {
  stage = score_engagement >= 55 && (lead.quoted_at || ctx.quoted_at) ? 'pregunto_no_concreto' : 'en_proceso';
}
if (stage !== 'concreto') {
  const blended = Math.round((score_engagement * 0.6) + ((100 - score_cierre) * 0.2) + ((100 - score_silencio) * 0.2));
  score_potencial = clamp(Math.max(score_potencial, blended), score_potencial);
}
return [{
  json: {
    lead_id: lead.id,
    stage,
    score_potencial,
    score_engagement,
    score_cierre,
    score_silencio,
    sentiment,
    reason: reason || 'Clasificación de conversación',
  },
}];

