const ctx = $('Armar contexto').first().json || {};
const parsed = $input.first().json || {};
let raw = parsed.text || parsed.output || parsed.response || parsed.message || '';
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw).toLowerCase();
const msg = String(ctx.mensaje || '').trim();
const contexto = String(ctx.contexto || '');
const imageSignal = String(ctx.image_signal || '');
if (imageSignal === 'pago' || imageSignal === 'reserva' || imageSignal === 'consulta') {
  return [{ json: { filter_label: 'relevante', message_id: ctx.message_id } }];
}
const captionMatch = msg.match(/Caption:\s*(.*)$/i);
const isImageNone = /^\[Imagen\b/i.test(msg) && imageSignal === 'ninguna';
const askText = isImageNone ? String(captionMatch ? captionMatch[1] : '') : msg;
const inFunnel = Boolean(ctx.quoted_at) || /(OPCIONES DISPONIBLES|FORMULARIO|cotizaci|habitaci|reserva con|€\d)/i.test(contexto);
const shortAck = /^(ok+|okay|okei|vale|si|sí|bueno|listo|gracias|dale|perfecto)[\s.!,]*$/i.test(askText);
const hotelAsk = /(precio|habitaci|disponib|reserv|fecha|noche|adulto|niñ|hosped|apartar|abonar|pagar|cotiz)/i.test(askText);
let label = 'irrelevante';
if (/\bspam\b/.test(raw)) label = 'spam';
else if (/\berror\b/.test(raw) && !/\brelevante\b/.test(raw)) label = 'error';
else if (shortAck && inFunnel) label = 'relevante';
else if (hotelAsk) label = 'relevante';
else if (/\brelevante\b/.test(raw) && !/\birrelevante\b/.test(raw)) label = 'relevante';
else if (/\birrelevante\b/.test(raw)) label = 'irrelevante';
else if (!isImageNone && inFunnel && msg.length > 0) label = 'relevante';
return [{ json: { filter_label: label, message_id: ctx.message_id } }];

const item = $input.first() || {};
const raw = item.json || {};
const nested = raw.data && typeof raw.data === 'object' ? raw.data : {};
let base64 = String(raw.base64 || raw.base64Data || nested.base64 || '');
base64 = base64.replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, '');
const mimetype = String(raw.mimetype || raw.mimeType || nested.mimetype || 'image/jpeg');
const err = raw.error || raw.message || '';
if (!base64 || base64.length < 32) {
  return [{ json: { media_ok: false, mimetype, error: String(err || 'sin base64') } }];
}
return [{ json: { media_ok: true, base64, mimetype } }];

const parsed = $input.first().json || {};
const prep = $('Preparar update').first().json || {};
const norm = $('Normalizar').first().json || {};
const extra = parsed.additional_kwargs || parsed.additionalKwargs || {};
let data = {};
let raw = '';
if (parsed.tipo || parsed.senal_embudo) {
  data = parsed;
  raw = JSON.stringify({
    tipo: parsed.tipo,
    texto_visible: parsed.texto_visible,
    senal_embudo: parsed.senal_embudo,
    resumen: parsed.resumen,
  });
} else {
  raw = parsed.text || parsed.output || parsed.response || parsed.message
    || parsed.reasoning_content || parsed.reasoning || extra.reasoning_content || '';
  if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
  raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw.startsWith('{')) {
    const dumped = JSON.stringify(parsed);
    const match = dumped.match(/\{[^{}]*"tipo"\s*:\s*"[^"]+"[^{}]*\}/);
    if (match) raw = match[0];
  }
  try {
    data = JSON.parse(raw);
  } catch (e) {
    data = {};
  }
}
const tipos = {
  comprobante_pago: true,
  cedula: true,
  formulario: true,
  screenshot_reserva: true,
  foto_habitacion: true,
  otro: true,
};
const senales = { pago: true, reserva: true, consulta: true, ninguna: true };
const mediaOk = !parsed.fallback && !parsed.error && raw.startsWith('{') && Boolean(data.tipo || data.senal_embudo);
const tipo = mediaOk && tipos[data.tipo] ? data.tipo : 'otro';
let senal = 'ninguna';
if (mediaOk && senales[data.senal_embudo]) senal = data.senal_embudo;
if (mediaOk && tipo === 'comprobante_pago') senal = 'pago';
const texto_visible = String(data.texto_visible || '').slice(0, 300);
const resumen = String(data.resumen || '').slice(0, 280);
const caption = String(norm.body || '').replace(/^\[Imagen enviada\]\s*/i, '').trim();
const analysis = mediaOk
  ? JSON.stringify({ tipo, texto_visible, senal_embudo: senal, resumen })
  : null;
const body = mediaOk
  ? [`[Imagen] tipo=${tipo} senal=${senal}: ${resumen || 'sin resumen'}`, texto_visible ? `Texto: ${texto_visible}` : '', caption ? `Caption: ${caption}` : ''].filter(Boolean).join(' ')
  : (caption ? `[Imagen no disponible] ${caption}` : '[Imagen no disponible]');
return [{
  json: {
    message_id: prep.message_id,
    media_analysis: analysis,
    media_signal: senal,
    body,
  },
}];

const item = $input.first() || {};
const raw = item.json || {};
const nested = raw.data && typeof raw.data === 'object' ? raw.data : {};
let base64 = String(raw.base64 || raw.base64Data || nested.base64 || '');
base64 = base64.replace(/^data:[a-zA-Z0-9.+-]+\/[a-zA-Z0-9.+-]+;base64,/, '');
const mimetype = String(raw.mimetype || raw.mimeType || nested.mimetype || 'audio/ogg');
const err = raw.error || raw.message || '';
if (!base64 || base64.length < 32) {
  return [{ json: { media_ok: false, mimetype, error: String(err || 'sin base64') } }];
}
return [{ json: { media_ok: true, base64, mimetype } }];

const raw = $input.first().json || {};
const prep = $('Preparar update').first().json || {};
const text = String(raw.text || '').replace(/\s+/g, ' ').trim();
const body = text ? `[Audio] ${text}` : '[Audio enviado]';
return [{
  json: {
    message_id: prep.message_id,
    body,
  },
}];
